        if (!(o instanceof BinaryTree)) return false;
        BinaryTree other = (BinaryTree) o;
        return treesEqual(root, other.root);
    }

    @Override
    public int hashCode() {
        return treesHash(root);
    }

    private static boolean treesEqual(Zipper a, Zipper b) {
        if (a == null) return b == null;
        if (b == null) return false;
        return a.getValue() == b.getValue()
            && treesEqual(a.left, b.left)
            && treesEqual(a.right, b.right);
    }

    private static int treesHash(Zipper n) {
